  "facts": [
    {
      "topic": "scope",
      "statement": "The entry takes an eight-byte options-and-width prefix, then treats the remaining bytes as Markdown. Its mode bits select document parsing, file parsing, incremental parsing, or direct Markdown-to-HTML conversion.",
      "evidence": [
        {"unit_id": "u-01d44c1169261cd79a4c", "start_line": 10, "end_line": 30, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-01d44c1169261cd79a4c", "start_line": 31, "end_line": 62, "role": "primary", "dependency_reason": ""}
      ]
   , "absence_claim": false, "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The harness masks options to seven named bits, including CMARK_OPT_VALIDATE_UTF8; that bit is defined as 1 << 9.",
      "evidence": [
        {"unit_id": "u-01d44c1169261cd79a4c", "start_line": 19, "end_line": 22, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-33ad62a4496f5ebacb21", "start_line": 620, "end_line": 620, "role": "dependency", "dependency_reason": "Defines the UTF-8 validation option admitted by the harness mask."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "For scanner input `a x=\"\\x80\">`, the before HTML tag scanner rejects the isolated 0x80 byte in the double-quoted attribute state: it takes the <=0xC1 branch to its zero-return state.",
      "evidence": [
        {"unit_id": "u-946a37c0fe8fac3957cc", "start_line": 5186, "end_line": 5204, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-946a37c0fe8fac3957cc", "start_line": 4953, "end_line": 4955, "role": "dependency", "dependency_reason": "The rejection state leads to the scanner's zero return."},
        {"unit_id": "u-946a37c0fe8fac3957cc", "start_line": 4890, "end_line": 4892, "role": "dependency", "dependency_reason": "Shows that the rejection path returns zero."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "For the same scanner input, the after HTML tag scanner's 0x80 table entry has the quoted-state continuation bit. It can continue through that byte, consume the closing quote and `>`, and return a positive match length.",
      "evidence": [
        {"unit_id": "u-105b2d533ce3f2b64287", "start_line": 4791, "end_line": 4801, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-105b2d533ce3f2b64287", "start_line": 5065, "end_line": 5089, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-105b2d533ce3f2b64287", "start_line": 4950, "end_line": 4952, "role": "dependency", "dependency_reason": "The accepting state returns the matched length."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "The target has multiple routes into document parsing: direct parsing, file parsing, incremental feed and finish, and Markdown-to-HTML conversion. A scanner-level difference alone therefore does not establish that the behavior is unreachable in the target.",
      "evidence": [
        {"unit_id": "u-01d44c1169261cd79a4c", "start_line": 29, "end_line": 62, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-16ced6e022a8e3e57bf9", "start_line": 561, "end_line": 569, "role": "dependency", "dependency_reason": "Direct document parsing feeds and finishes a parser."},
        {"unit_id": "u-84446617c1ab4ffb70a7", "start_line": 38, "end_line": 47, "role": "dependency", "dependency_reason": "Markdown-to-HTML conversion delegates to document parsing."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "The complete harness entry contains no assertion or output comparison. It renders and frees the returned outputs when a document exists, then returns zero.",
      "evidence": [
        {"unit_id": "u-01d44c1169261cd79a4c", "start_line": 64, "end_line": 75, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": true,
      "audited_unit_ids": ["u-01d44c1169261cd79a4c"]
    },
    {
      "topic": "configuration",
      "statement": "The supplied build recipe runs CMake with no explicit options, builds cmark_static, then links the harness against libcmark.a.",
